{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Ketoprofen, a lipophilic acidic drug, has absolute oral bioavailability of 92% in humans, supporting high F for the similarly acidic, lipophilic warfarin-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Diflunisal, an acidic salicylic acid derivative, showed 89.5% absolute oral bioavailability, supporting high F for the acidic 4-hydroxycoumarin query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Baclofen, despite a polar zwitterionic structure, reaches approximately 80% oral bioavailability, showing that moderate polarity does not preclude high F and supporting high F for the less polar query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Felbamate has about 90% oral bioavailability in humans, supporting high F for a small orally absorbed drug, though structural transfer is limited.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Modafinil, a diphenylmethyl-containing drug, has at least 40-65% oral bioavailability, well above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Baicalein has low oral bioavailability, but its polyphenolic flavone structure with poor solubility/metabolism liabilities transfers poorly to the lipophilic warfarin-like query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C28"],
      "claim": "Cromolyn has <1% oral bioavailability due to very poor absorption, but its highly polar, ionized chromone structure is far from the lipophilic warfarin-like query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is warfarin, a lipophilic acidic 4-hydroxycoumarin. Multiple relevant analogues with high oral bioavailability (ketoprofen 92%, diflunisal 89.5%, baclofen ~80%, felbamate 90%, modafinil 40-65%) support F >=20%. Low-F analogues (baicalein, cromolyn) are much more polar/poorly soluble and transfer poorly. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental record for warfarin itself in the supplied evidence.",
    "All retrieved analogues have low Morgan similarity (<0.3), limiting quantitative transferability.",
    "No dose/formulation-specific absolute bioavailability data for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

